function makeCrab(species,scale=1){
  const group=new THREE.Group(),shellMat=mat(species.color,.48,.08),edgeMat=mat(new THREE.Color(species.color).multiplyScalar(.62),.56),jointMat=mat('#d0a083',.42),eyeMat=mat('#1b2422',.2);
  const shell=new THREE.Mesh(new THREE.SphereGeometry(.42,20,14),shellMat);shell.scale.set(1.25,.48,.83);shell.position.y=.12;shell.castShadow=true;group.add(shell);
  const apron=new THREE.Mesh(new THREE.SphereGeometry(.22,12,8),edgeMat);apron.scale.set(1,.32,.76);apron.position.set(0,-.04,.2);group.add(apron);
  for(const side of [-1,1]){
    const stalk=new THREE.Mesh(new THREE.CylinderGeometry(.025,.045,.18,8),jointMat);stalk.position.set(side*.28,.29,-.25);stalk.rotation.z=-side*.22;group.add(stalk);
    const eye=new THREE.Mesh(new THREE.SphereGeometry(.065,10,8),eyeMat);eye.position.set(side*.3,.39,-.25);group.add(eye);
    for(let i=0;i<4;i++){const x=side*(.29+i*.035),z=-.18+i*.13;const leg=new THREE.Group();leg.position.set(x,-.02,z);const upper=new THREE.Mesh(new THREE.CylinderGeometry(.035,.05,.27,8),shellMat);upper.rotation.z=side*(.72+i*.06);upper.position.x=side*.09;leg.add(upper);const lower=new THREE.Mesh(new THREE.CylinderGeometry(.022,.035,.28,8),jointMat);lower.rotation.z=-side*.7;lower.position.set(side*.22,-.13,0);leg.add(lower);const tip=new THREE.Mesh(new THREE.ConeGeometry(.035,.11,7),edgeMat);tip.position.set(side*.3,-.27,0);tip.rotation.z=Math.PI;leg.add(tip);group.add(leg)}
    const arm=new THREE.Mesh(new THREE.CylinderGeometry(.055,.085,.25,10),shellMat);arm.position.set(side*.53,.04,-.31);arm.rotation.z=-side*.78;group.add(arm);
    const claw=new THREE.Mesh(new THREE.SphereGeometry(.16,12,9),shellMat);claw.scale.set(.82,.78,1);claw.position.set(side*.68,.12,-.38);group.add(claw);
    for(const fingerSide of [-1,1]){const finger=new THREE.Mesh(new THREE.ConeGeometry(.055,.2,8),jointMat);finger.position.set(side*.72,.02,-.38+fingerSide*.09);finger.rotation.z=side*(fingerSide>0?-.75:.15);group.add(finger)}
  }
  group.scale.setScalar(scale*Math.max(.7,species.length*.42));return group;
}
