 function selectFish(){const bait=currentBait();const hour=state.hours%24;const depth=state.depth;let pool=fishSpecies.filter(f=>!f.variant&&Math.abs(f.depth-depth)<34);if(bait.tags.includes('deep'))pool=pool.filter(f=>f.depth>45);if(bait.tags.includes('bottom'))pool=pool.filter(f=>f.depth>25);if(bait.tags.includes('small'))pool=pool.filter(f=>f.maxSize<75);if(hour>19||hour<5)pool=pool.filter(f=>f.speciesIndex%3!==0);if(!pool.length)pool=fishSpecies.filter(f=>!f.variant).sort((a,b)=>Math.abs(a.depth-depth)-Math.abs(b.depth-depth)).slice(0,24);const specialChance=state.upgrades.includes('sonar')?.16:.055;const special=Math.random()<specialChance;let fish;if(special){const variants=fishSpecies.filter(f=>f.variant&&Math.abs(f.depth-depth)<42);fish=variants[Math.floor(Math.random()*variants.length)]}else{const weighted=pool.map(f=>Math.exp(-Math.abs(f.depth-depth)/19)*(1+Math.max(0,depth-45)/220));const ticket=Math.random()*weighted.reduce((a,b)=>a+b,0);let sum=0;fish=pool.find((f,i)=>(sum+=weighted[i])>=ticket)||pool[pool.length-1]}return fish||fishSpecies[0]}
